data.minimal_example:
ReorderableGridView.count(
  crossAxisCount: 3,
  children: data.map((e) => Card(key: ValueKey(e), child: Text('$e'))).toList(),
  onReorder: (oldIndex, newIndex) {
    setState(() {
      final element = data.removeAt(oldIndex);
      data.insert(newIndex, element);
    });
  },
)
